def can_make_abc(cards):
    # Check if the cards are already in the order 'abc'
    if cards == 'abc':
        return True

    # Check if swapping any two cards can result in 'abc'
    for i in range(3):
        for j in range(i + 1, 3):
            if cards[i] == 'a' and cards[j] == 'b':
                return True
            elif cards[i] == 'b' and cards[j] == 'c':
                return True
            elif cards[i] == 'c' and cards[j] == 'a':
                return True

    return False

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        cards = input[i]
        if can_make_abc(cards):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

def count_passengers_over_60(details):
    count = 0
    for detail in details:
        age = int(detail[12:14])
        if age > 60:
            count += 1
    return count

def maximumOr(nums, k):
    max_or = 0
    for i in range(len(nums)):
        current_or = nums[i]
        for _ in range(k):
            current_or |= nums[i]
            nums[i] *= 2
        max_or = max(max_or, current_or)
    return max_or

def maxStrength(nums):
    max_strength = float('-inf')
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            product = 1
            for k in range(i, j+1):
                product *= nums[k]
            max_strength = max(max_strength, product)
    return max_strength

def minExtraChar(s, dictionary):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + 1
        for j in range(i):
            if s[j:i] in dictionary:
                dp[i] = min(dp[i], dp[j])

    return dp[n]

def buyTwoChocolates(prices, money):
    prices.sort()
    total = 0
    for i in range(len(prices) - 1):
        total += prices[i]
        if total > money:
            return money
    return money - total

def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7

    def digit_sum(x):
        return sum(int(digit) for digit in str(x))

    count = 0
    for x in range(int(num1), int(num2) + 1):
        if min_sum <= digit_sum(x) <= max_sum:
            count += 1

    return count % MOD

def color_and_count(n, queries):
    nums = [0] * n
    answer = []
    for index, color in queries:
        nums[index] = color
        count = 0
        for i in range(n - 1):
            if nums[i] == nums[i + 1] and nums[i] != 0:
                count += 1
        answer.append(count)
    return answer

def longest_semi_repetitive_substring(s):
    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            current_length += 1
        else:
            current_length = 2
        max_length = max(max_length, current_length)

    return max_length

def findLosers(n, k):
    visited = [False] * n
    losers = []
    current_position = 0

    while not visited[current_position]:
        visited[current_position] = True
        current_position = (current_position + k) % n

        if current_position == 0:
            losers.append(current_position + 1)

    return losers

def validArray(derived):
    if len(derived) == 1:
        return True

    for i in range(len(derived)):
        if derived[i] == 1:
            if i == 0:
                return False
            if i == len(derived) - 1:
                return False
            if derived[i - 1] == derived[i + 1]:
                return False

    return True

def min_length(s):
    stack = []
    for char in s:
        if char == 'B' and stack and stack[-1] == 'A':
            stack.pop()
        elif char == 'D' and stack and stack[-1] == 'C':
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

def is_punishment_number(i):
    def can_partition(s, target):
        if target == 0:
            return True
        if target < 0 or not s:
            return False
        for j in range(1, len(s) + 1):
            if can_partition(s[j:], target - int(s[:j])):
                return True
        return False

    square = str(i * i)
    return can_partition(square, i)

def punishment_number(n):
    punishment_sum = 0
    for i in range(1, n + 1):
        if is_punishment_number(i):
            punishment_sum += i * i
    return punishment_sum

def minCost(cost, time):
    n = len(cost)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(i):
            if time[j] >= time[i - 1]:
                dp[i] = min(dp[i], dp[j] + cost[j])

    return dp[n]

def minCost(nums, x):
    n = len(nums)
    dp = [float('inf')] * n
    dp[0] = nums[0]

    for i in range(1, n):
        dp[i] = min(dp[i], dp[(i - 1) % n] + nums[i])
        dp[i] = min(dp[i], dp[(i - 1) % n] + nums[i] + x)

    return min(dp)

def minimum_sum(n, k):
    dp = [0] * (k + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        for j in range(k, 0, -1):
            dp[j] = max(dp[j], dp[j - i] + i)
    return dp[k]

def make_lexicographically_smallest_palindrome(s):
    s = list(s)
    n = len(s)
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            s[i] = 'a'
            s[n - i - 1] = 'a'
    return ''.join(s)

def min_cost_to_make_all_equal(s):
    n = len(s)
    dp = [0] * n

    for i in range(n):
        if s[i] == '0':
            dp[i] = i + 1
        else:
            dp[i] = n - i

    for i in range(1, n):
        dp[i] = min(dp[i], dp[i-1] + 1)

    return dp[-1]

def is_fascinating(n):
    concatenated = str(n) + str(2 * n) + str(3 * n)
    return set(concatenated) == set('123456789')

def minimizedStringLength(s: str) -> int:
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

