def longest_equal_subarray(nums, k):
    n = len(nums)
    left = 0
    max_length = 0
    zero_count = 0

    for right in range(n):
        if nums[right] == nums[left]:
            zero_count += 1

        while zero_count > k:
            if nums[left] == nums[left + 1]:
                zero_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

