MOD = 10**9 + 7

def count_special_permutations(nums):
    def dfs(index, prev):
        if index == len(nums):
            return 1
        count = 0
        for i in range(len(nums)):
            if i != index and nums[i] % nums[index] == 0 or nums[index] % nums[i] == 0:
                count += dfs(index + 1, nums[i])
                count %= MOD
        return count

    return dfs(0, -1)

def sum_imbalance_numbers(nums):
    n = len(nums)
    total_imbalance = 0

    for i in range(n):
        sarr = sorted(nums[i:])
        imbalance = 0
        for j in range(i + 1, n):
            if sarr[j] - sarr[j - 1] > 1:
                imbalance += 1
            else:
                break
        total_imbalance += imbalance

    return total_imbalance

def min_length(words):
