    for i in range(1, len(words)):
        dp[i] = min(dp[i-1] + len(words[i]), dp[i-1] + len(words[i]) - 1)
    return dp[-1]

def maxJumps(nums, target):
    n = len(nums)
    dp = [float('inf')] * n
    dp[0] = 0

    for i in range(n):
        for j in range(i + 1, n):
            if -target <= nums[j] - nums[i] <= target:
                dp[j] = min(dp[j], dp[i] + 1)

    return dp[n - 1] if dp[n - 1] != float('inf') else -1

def countCompleteSubarrays(nums):
    distinct_count = len(set(nums))
    n = len(nums)
    count = 0

    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(nums[j])
            if len(seen) == distinct_count:
                count += 1

    return count

