def max_alternating_subarray_length(nums):
    max_length = -1
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            subarray = nums[i:j+1]
            if len(subarray) > 1 and subarray[1] - subarray[0] == 1 and all(subarray[k] - subarray[k-1] == (-1) ** (k+1) for k in range(1, len(subarray))):
