def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_pairs(n):
    pairs = []
    for x in range(2, n // 2 + 1):
        if is_prime(x) and is_prime(n - x):
            pairs.append([x, n - x])
    return pairs

