def min_changes_to_semi_palindrome(s, k):
    def is_semi_palindrome(sub):
        n = len(sub)
        for d in range(1, n):
            if n % d == 0:
                for i in range(d):
                    left = i
                    right = n - 1 - i
                    while left < right:
                        if sub[left] != sub[right]:
                            return False
                        left += d
                        right -= d
                return True
        return True

    def min_changes(sub):
        n = len(sub)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 0
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if sub[i] == sub[j]:
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i + 1][j], dp[i][j - 1])
        return dp[0][n - 1]

    def min_changes_to_k_semi_palindromes(s, k):
        n = len(s)
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            for j in range(1, min(i, k) + 1):
                for l in range(i):
                    dp[i][j] = min(dp[i][j], dp[l][j - 1] + min_changes(s[l:i]))
        return dp[n][k]

    return min_changes_to_k_semi_palindromes(s, k)

def split_strings(words, separator):
    result = []
    for word in words:
        split_words = word.split(separator)
