def count_ways(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i - j**x >= 0:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def min_beautiful_substrings(s):
    def is_power_of_5(n):
        if n == 0:
            return True
        while n % 5 == 0:
            n //= 5
        return n == 1

    def dfs(start, count):
        if start == len(s):
            return count
        if s[start] == '0':
            return float('inf')
        for end in range(start + 1, len(s) + 1):
            substring = s[start:end]
            if is_power_of_5(int(substring, 2)):
                return dfs(end, count + 1)
        return float('inf')

    return dfs(0, 0)

