def finalString(s: str) -> str:
    result = []
    for char in s:
        if char == 'i':
            result.reverse()
        else:
            result.append(char)
    return ''.join(result)

def permute_string(s):
    vowels = 'aeiouAEIOU'
    consonants = [c for c in s if c not in vowels]
    vowels_sorted = sorted([c for c in s if c in vowels])
    result = []
    consonant_index = 0
    vowel_index = 0
    for c in s:
        if c in vowels:
            result.append(vowels_sorted[vowel_index])
            vowel_index += 1
        else:
            result.append(consonants[consonant_index])
            consonant_index += 1
    return ''.join(result)

def minimum_index(nums):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    dominant_element = max(freq, key=freq.get)

    left_freq = 0
    for i, num in enumerate(nums):
        if num == dominant_element:
            left_freq += 1
        freq[num] = freq.get(num, 0) - 1

        if i > 0 and num == dominant_element:
            right_freq = freq.get(dominant_element, 0)
            if left_freq * 2 > i + 1 and right_freq * 2 > n - i - 1:
                return i

    return -1

def maximumBeauty(nums, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    max_beauty = 0

    while left < right:
        if nums[right] - nums[left] <= 2 * k:
            max_beauty = max(max_beauty, right - left + 1)
            right -= 1
        else:
            left += 1

    return max_beauty

def is_good(nums):
    max_num = max(nums)
    n = max_num
    if len(nums) != n + 1:
        return False
    base = list(range(1, n)) + [n, n]
    return sorted(nums) == sorted(base)

def max_sum_with_equal_max_digit(nums):
