def countInterestingSubarrays(nums, modulo, k):
    count = 0
    prefix_count = 0
    prefix_count_mod = 0

    for num in nums:
        if num % modulo == k:
            prefix_count += 1
        prefix_count_mod = (prefix_count_mod + prefix_count) % modulo

        if prefix_count_mod == k:
            count += 1

        if prefix_count_mod < k:
            count += prefix_count_mod

    return count

def canSplitArray(nums, m):
    if len(nums) == 1:
        return True

    def canSplit(nums, m):
        if len(nums) == 1:
            return True

        for i in range(1, len(nums)):
            if nums[i] >= m:
                return canSplit(nums[:i], m) or canSplit(nums[i+1:], m)

        return False

    return canSplit(nums, m)

