    return groups

MOD = 10**9 + 7

def count_stepping_numbers(low, high):
    def dfs(pos, prev_digit, is_low, is_high, count):
        if pos == len(high):
            return count

        if is_low and int(high[pos]) < int(low[pos]):
            return 0

        count = 0
        if pos > 0:
            count += dfs(pos - 1, int(high[pos]) - 1, is_low and int(high[pos]) == int(low[pos]), is_high and int(high[pos]) == int(low[pos]), count)

        if pos > 0:
            count += dfs(pos - 1, int(high[pos]) + 1, is_low and int(high[pos]) == int(low[pos]), is_high and int(high[pos]) == int(low[pos]), count)

        return count % MOD

    count = 0
    for i in range(1, 10):
        count += dfs(0, i, True, True, 0)

    return count

def count_pairs(coordinates, k):
    count = 0
    reference_point = (0, 0)
    distance_map = {}
    for x, y in coordinates:
        distance = (x ^ reference_point[0]) + (y ^ reference_point[1])
        if distance not in distance_map:
            distance_map[distance] = []
        distance_map[distance].append((x, y))
    for x, y in coordinates:
        distance = (x ^ reference_point[0]) + (y ^ reference_point[1])
        if distance in distance_map:
            for x2, y2 in distance_map[distance]:
                if (x2 ^ x) + (y2 ^ y) == k:
                    count += 1
    return count

