def maximizeTheProfit(n, offers):
    dp = [0] * (n + 1)
    for start, end, gold in offers:
        for i in range(start, end + 1):
            dp[i] = max(dp[i], dp[i - 1] + gold)
    return dp[n - 1]

def count_symmetric_integers(low, high):
    def is_symmetric(num):
        num_str = str(num)
        if len(num_str) % 2 != 0:
            return False
        mid = len(num_str) // 2
        return sum(int(num_str[i]) for i in range(mid)) == sum(int(num_str[i]) for i in range(mid, len(num_str)))

    count = 0
    for num in range(low, high + 1):
        if is_symmetric(num):
            count += 1
    return count

