def can_make_subsequence(str1, str2):
    def next_char(c):
        return chr((ord(c) - ord('a') + 1) % 26 + ord('a'))

    i, j = 0, 0
    while i < len(str1) and j < len(str2):
        if str1[i] == str2[j]:
            j += 1
        i += 1

    if j == len(str2):
        return True

    # Try to find a way to make str2 a subsequence by incrementing one character in str1
    for i in range(len(str1)):
        if str1[i] != str2[j]:
            # Increment str1[i] to the next character cyclically
            str1 = str1[:i] + next_char(str1[i]) + str1[i+1:]
            if can_make_subsequence(str1, str2):
                return True
            # Revert the change
            str1 = str1[:i] + str1[i] + str1[i+1:]

    return False

def minOperations(nums, target):
    operations = 0
    while target > 0:
        found = False
        for i in range(len(nums)):
            if nums[i] > target:
                break
            if target >= nums[i]:
                target -= nums[i]
                nums[i] = 0
                found = True
                break
        if not found:
            return -1
        operations += 1
    return operations

def product_matrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[1] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            p[i][j] = (grid[i][0] * grid[i][1] * ... * grid[i][m-1]) % 12345

    return p

def getMaxFunctionValue(receiver, k):
    n = len(receiver)
    max_value = 0

    for start in range(n):
        current_sum = start
        for _ in range(k):
            current_sum += receiver[current_sum]
            current_sum %= n
        max_value = max(max_value, current_sum)

    return max_value

