def min_operations_to_special(num: str) -> int:
    n = len(num)
    dp = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = dp[i + 1][j] + 1
            if num[i] == '0' and num[j] == '0':
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
            if num[i] == '0' and num[j] == '5':
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
            if num[i] == '5' and num[j] == '0':
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
            if num[i] == '5' and num[j] == '5':
                dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])

    return dp[0][n - 1]

import math

def is_perfect_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def max_element_sum_of_complete_subset(nums):
    n = len(nums)
    max_sum = 0

    for i in range(1, n + 1):
        for j in range(i, n + 1, i):
            subset_sum = sum(nums[k - 1] for k in range(i, j + 1))
            if is_perfect_square(subset_sum):
                max_sum = max(max_sum, subset_sum)

    return max_sum

