    max_subarrays = 0
    current_and = nums[0]
    for i in range(1, len(nums)):
        current_and &= nums[i]
        if current_and == 0:
            max_subarrays += 1
            current_and = nums[i]
    max_subarrays += 1
    return max_subarrays

def min_length(nums):
    i, j = 0, len(nums) - 1
    while i < j:
        if nums[i] < nums[j]:
            i += 1
        else:
            j -= 1
    return len(nums) - (i + 1)

def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    dp = [0] * (r + 1)
    dp[0] = 1
    for num in nums:
        for i in range(r, num - 1, -1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    return sum(dp[l:r + 1]) % MOD

def sum_of_elements_with_k_set_bits(nums, k):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    return sum(nums[i] for i in range(len(nums)) if count_set_bits(i) == k)

