def longest_subsequence(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1
    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = max(dp[i], dp[i - num] + 1)
    return dp[target] if dp[target] > 0 else -1

def min_subarray_len(nums, target):
    n = len(nums)
    total_sum = sum(nums)
    if target % total_sum != 0:
        return -1
    target = target // total_sum
    prefix_sum = [0] * (2 * n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + nums[i]
    min_len = float('inf')
    for i in range(n, 2 * n + 1):
        if prefix_sum[i] - target in prefix_sum:
            min_len = min(min_len, i - prefix_sum.index(prefix_sum[i] - target))
    return min_len if min_len != float('inf') else -1

def shortest_beautiful_substring(s, k):
    n = len(s)
    count = 0
    min_len = float('inf')
    result = ""

    for i in range(n):
        count = 0
        for j in range(i, n):
            if s[j] == '1':
                count += 1
            if count == k:
                if j - i + 1 < min_len:
                    min_len = j - i + 1
                    result = s[i:j+1]
                elif j - i + 1 == min_len:
                    result = min(result, s[i:j+1])
                count = 0

    return result

def minTimeToExecuteTasks(processorTime, tasks):
    tasks.sort()
    processorTime.sort()

    # Assign the smallest tasks to the first processor
    for i in range(len(tasks)):
        processorTime[i] += tasks[i]

    # Assign the remaining tasks to the second processor
    for i in range(len(tasks)):
        processorTime[i] += tasks[i]

    # The minimum time to execute all tasks is the maximum time taken by any processor
    return max(processorTime)

