def min_sum(nums1, nums2):
    sum1, sum2 = sum(nums1), sum(nums2)
    zeros1, zeros2 = nums1.count(0), nums2.count(0)

    if zeros1 > zeros2:
        return -1

    for i in range(zeros1):
        if sum1 + i > sum2:
            return -1
        sum1 += i

    for i in range(zeros2):
        if sum2 + i > sum1:
            return -1
        sum2 += i

    return sum1

