def minimum_sum_of_mountain_triplet(nums):
    n = len(nums)
    min_sum = float('inf')

    for j in range(1, n-1):
        left_min = float('inf')
        right_min = float('inf')

        for i in range(j):
            if nums[i] < nums[j]:
                left_min = min(left_min, nums[i])

        for k in range(j+1, n):
            if nums[k] < nums[j]:
                right_min = min(right_min, nums[k])

        if left_min != float('inf') and right_min != float('inf'):
            min_sum = min(min_sum, left_min + nums[j] + right_min)

    return min_sum if min_sum != float('inf') else -1

def k_or(nums, k):
    result = 0
    for i in range(31):
        count = 0
        for num in nums:
            if (num & (1 << i)) != 0:
                count += 1
        if count >= k:
            result |= (1 << i)
    return result

