def can_make_palindrome(s, queries):
    n = len(s)
    half = n // 2

    def is_palindrome(sub):
        return sub == sub[::-1]

    def can_form_palindrome(sub):
        count = [0] * 26
        for char in sub:
            count[ord(char) - ord('a')] += 1
        odd_count = 0
        for c in count:
            if c % 2 == 1:
                odd_count += 1
        return odd_count <= 1

    answer = []
    for a, b, c, d in queries:
        # Rearrange s[a:b] and s[c:d]
        s_a_b = s[a:b+1]
        s_c_d = s[c:d+1]

        # Check if s_a_b and s_c_d can be rearranged to form a palindrome
        if can_form_palindrome(s_a_b) and can_form_palindrome(s_c_d):
            # Check if the remaining parts of s can form a palindrome
            remaining_a = s[:a] + s[b+1:]
            remaining_b = s[:b] + s[a+1:]
            remaining_c = s[c:d+1]
            remaining_d = s[d+1:]

            # Check if the remaining parts can be rearranged to form a palindrome
            if can_form_palindrome(remaining_a) and can_form_palindrome(remaining_b) and can_form_palindrome(remaining_c) and can_form_palindrome(remaining_d):
                answer.append(True)
