def earliest_second_to_mark_all_indices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)

    # Create a list to store the number of decrements needed for each index
    decrements = [0] * n

    # Calculate the number of decrements needed for each index
    for i in range(n):
        if nums[i] > 0:
            decrements[i] = nums[i]

    # Create a list to store the indices that need to be marked
    marked_indices = [False] * n

    # Create a list to store the indices that need to be decremented
    decrement_indices = []

    # Iterate through the changeIndices list
    for s in range(m):
        if changeIndices[s] - 1 in decrements:
            marked_indices[changeIndices[s] - 1] = True
        elif decrements[changeIndices[s] - 1] > 0:
            decrement_indices.append(changeIndices[s] - 1)
        else:
            return -1

    # If all indices are marked, return the current second
    if all(marked_indices):
        return s + 1

    # If not all indices are marked, return -1
    return -1

