def max_subset_size(nums):
    num_set = set(nums)
    max_size = 0

    for num in num_set:
        size = 1
        power = 1
        while power * power <= num:
            if power * power == num:
                size += 1
            power *= 2
        max_size = max(max_size, size)

    return max_size

