def can_split(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for key, value in count.items():
        if value > 1:
            return False

    return True

def longest_common_prefix(arr1, arr2):
    def common_prefix(a, b):
        prefix = ""
        for i in range(min(len(a), len(b))):
            if a[i] == b[i]:
                prefix += a[i]
            else:
                break
        return prefix

    max_length = 0
    for a in arr1:
        for b in arr2:
            if a != b:
                max_length = max(max_length, len(common_prefix(a, b)))

    return max_length

def min_operations(nums, k):
    operations = 0
    while min(nums) < k:
        nums.remove(min(nums))
        operations += 1
    return operations

def distribute_elements(nums):
    arr1, arr2 = [], []
    for i in range(len(nums)):
        if len(arr1) == 0 or arr1[-1] > arr2[-1]:
            arr1.append(nums[i])
        else:
            arr2.append(nums[i])
    return arr1 + arr2

def determine_overall_winner(N, S):
    takahashi_wins = 0
    aoki_wins = 0

    for i in range(N):
        if S[i] == 'T':
            takahashi_wins += 1
        elif S[i] == 'A':
            aoki_wins += 1

    if takahashi_wins > aoki_wins:
        return 'T'
    elif aoki_wins > takahashi_wins:
        return 'A'
    else:
        # If both have the same number of wins, determine the winner based on the first occurrence
        first_takahashi_win = -1
        first_aoki_win = -1
        for i in range(N):
            if S[i] == 'T':
                first_takahashi_win = i + 1
                break
        for i in range(N):
            if S[i] == 'A':
                first_aoki_win = i + 1
                break

        if first_takahashi_win < first_aoki_win:
            return 'T'
        else:
            return 'A'

