def insert_numbers(sequence):
    while True:
        if abs(sequence[-1] - sequence[-2]) == 1:
            break
        i = sequence.index(sequence[-1])
        j = sequence.index(sequence[-2])
        if sequence[i] < sequence[j]:
            sequence = sequence[:i] + list(range(sequence[i], sequence[j])) + sequence[j:]
        else:
            sequence = sequence[:j] + list(range(sequence[j], sequence[i], -1)) + sequence[i:]
    return sequence

