def generate_binary_numbers(S, index=0, current_number=0, result=None):
    if result is None:
        result = []
    if index == len(S):
        result.append(current_number)
        return result
    if S[index] == '?':
        generate_binary_numbers(S, index + 1, current_number * 2 + 0, result)
        generate_binary_numbers(S, index + 1, current_number * 2 + 1, result)
    else:
        generate_binary_numbers(S, index + 1, current_number * 2 + int(S[index]), result)
    return result

def find_greatest_number_less_than_or_equal_to_N(S, N):
    T = generate_binary_numbers(S)
    T = [num for num in T if num <= N]
    if T:
        return max(T)
    else:
        return -1

