from collections import deque

def bfs(grid, start, goal, T):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(start[0], start[1], 0, set())])
    visited = set()
    visited.add((start[0], start[1], 0))

    while queue:
        x, y, moves, candies = queue.popleft()

        if (x, y) == goal and moves <= T:
            return len(candies)

        if moves >= T:
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                new_candies = candies.copy()
                if grid[nx][ny] == 'o':
                    new_candies.add((nx, ny))

                if (nx, ny, moves + 1) not in visited:
                    visited.add((nx, ny, moves + 1))
                    queue.append((nx, ny, moves + 1, new_candies))

    return -1

def main():
    import sys
    input = sys.stdin.read().split()
