def count_ways(S):
    n = len(S)
    dp = [[[0] * 26 for _ in range(26)] for _ in range(26)]

    # Initialize the base cases
    for i in range(n):
        if S[i] == '?':
            for j in range(26):
                for k in range(26):
                    dp[j][k][26] = 1
        else:
            j = ord(S[i]) - ord('A')
            k = ord(S[i]) - ord('a')
            dp[j][k][26] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(26):
            for k in range(26):
                for l in range(26):
                    if S[i] == '?':
                        for c in range(26):
                            dp[j][k][l] = (dp[j][k][l] + dp[j][k][l]) % MOD
                    else:
                        j = ord(S[i]) - ord('A')
                        k = ord(S[i]) - ord('a')
                        if j == k:
                            dp[j][k][l] = (dp[j][k][l] + dp[j][k][l]) % MOD
                        else:
                            dp[j][k][l] = (dp[j][k][l] + dp[j][k][l]) % MOD

    # Sum up all valid ways
    result = 0
    for j in range(26):
        for k in range(26):
            for l in range(26):
                result = (result + dp[j][k][l]) % MOD

    return result

