from collections import defaultdict, deque

def find_connected_components(N, M, sets):
    graph = defaultdict(list)
    for i in range(N):
        for j in range(len(sets[i])):
            for k in range(i + 1, N):
                if sets[k][j] in sets[i]:
                    graph[i].append(k)
                    graph[k].append(i)

    visited = [False] * N
    components = []

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        component = [start]
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    component.append(neighbor)
                    queue.append(neighbor)
        return component

    for i in range(N):
        if not visited[i]:
            components.append(bfs(i))

    return components

def min_operations_to_merge(N, M, sets):
    components = find_connected_components(N, M, sets)
    min_operations = float('inf')

    for component in components:
        if 1 in component and M in component:
            min_operations = min(min_operations, len(component) - 1)

    return min_operations if min_operations != float('inf') else -1

