    # Function to check if a given area on sheet C matches sheet X
    def matches_X(C, X, top_left):
        for i in range(H_X):
            for j in range(W_X):
                if C[top_left[0] + i][top_left[1] + j] != X[i][j]:
                    return False
        return True

    # Try all possible placements of sheets A and B on sheet C
    for i in range(H_A + H_B + 1):
        for j in range(W_A + W_B + 1):
            # Create a new sheet C with dimensions (i+H_A) x (j+W_A)
            C = [['.' for _ in range(j + W_A)] for _ in range(i + H_A)]

            # Paste sheet A onto sheet C
            for a in range(H_A):
                for b in range(W_A):
                    C[a][b] = A[a][b]

            # Paste sheet B onto sheet C
            for b in range(H_B):
                for a in range(W_B):
                    C[a][b] = B[b][a]

            # Try all possible cut-out areas
            for top_left in [(i, j)]:
                for bottom_right in [(i + H_X - 1, j + W_X - 1)]:
                    if matches_X(C, X, top_left):
                        return "Yes"

    return "No"

