def count_ways(N, M):
    if N == 1:
        return M
    if M == 1:
        return 0

    dp = [[0] * M for _ in range(M)]

    for i in range(M):
        dp[i][i] = 1

    for i in range(1, M):
        for j in range(1, M):
            dp[i][j] = (dp[i][j-1] + dp[i-1][j]) % MOD

    return dp[M-1][0]

