    # Define the target sequence
    target_sequence = "snuke"

    # Create a dictionary to store the positions of each character in the target sequence
    positions = {char: [] for char in target_sequence}
    for i in range(H):
        for j in range(W):
            if grid[i][j] == target_sequence[0]:
                positions[target_sequence[0]].append((i, j))

    # Use a queue to perform BFS
    from collections import deque
    queue = deque([(0, 0)])  # Start from (0, 0) which is (1, 1) in 1-based indexing
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y = queue.popleft()

        # Check if we have reached the end
        if (x, y) == (H-1, W-1):
            return True

        # Check if the current cell matches the next character in the target sequence
        if grid[x][y] == target_sequence[1]:
            next_char = target_sequence[1]
            if next_char not in positions:
                return False

            # Check if the next cell is valid and not visited
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and (nx, ny) not in visited:
