def count_holeless_squares(H, W, N, holed_squares):
    # Initialize the grid with 0s
    grid = [[0] * W for _ in range(H)]

    # Mark the holed squares
    for a, b in holed_squares:
        grid[a - 1][b - 1] = 1

    # Function to check if a square of size n starting at (i, j) is holeless
    def is_holeless(i, j, n):
        for k in range(n):
            for l in range(n):
                if grid[i + k][j + l] == 1:
                    return False
        return True

    # Count the holeless squares
    holeless_count = 0
    for i in range(H):
        for j in range(W):
            for n in range(1, min(H - i, W - j) + 1):
                if is_holeless(i, j, n):
                    holeless_count += 1

    return holeless_count

