def count_parenthesis_strings(S):
    def count_ways(S, left, right, question_marks):
        if left > right:
            return 0
        if left == right == 0:
            return 1
        if left > right:
            return 0

        ways = 0
        for i in range(question_marks):
            ways += count_ways(S, left + 1, right, question_marks - 1)
            ways %= MOD
            ways += count_ways(S, left, right + 1, question_marks - 1)
            ways %= MOD
        return ways

    return count_ways(S, 0, 0, S.count('?'))

