def find_strongest_programmer(N, M, relations):
    # Create a graph to represent the superiority relations
    graph = {i: [] for i in range(1, N + 1)}
    for A, B in relations:
        graph[A].append(B)
        graph[B].append(A)

    # Perform a DFS to find the strongest programmer
    def dfs(person, visited):
        visited.add(person)
        for neighbor in graph[person]:
            if neighbor not in visited:
                dfs(neighbor, visited)

    # Try to find the strongest programmer by checking each person
    for person in range(1, N + 1):
        visited = set()
        dfs(person, visited)
        if len(visited) == N:
            return person

    # If no single person can be the strongest, return -1
    return -1

