def process_operations(N, S, Q, operations):
    # Initialize a dictionary to keep track of changes
    changes = {}

    # Process each operation
    for t, x, c in operations:
        if t == 1:
            # Change the x-th character to c
            if x in changes:
                changes[x] = c
            else:
                changes[x] = c
        elif t == 2:
            # Convert all uppercase letters to lowercase
            for i in range(N):
                if S[i].isupper():
                    S[i] = S[i].lower()
        elif t == 3:
            # Convert all lowercase letters to uppercase
            for i in range(N):
                if S[i].islower():
                    S[i] = S[i].upper()

    # Apply the changes to the final string
    final_string = []
    for i in range(N):
        if i in changes:
            final_string.append(changes[i])
        else:
            final_string.append(S[i])

    return ''.join(final_string)

