def solve_cookie_problem(H, W, cookies):
    # Step 1: Mark cookies in each row
    for i in range(H):
        row = cookies[i]
        if len(set(row)) > 1:
            for j in range(W):
                if row[j] == row[j+1]:
                    row[j] = '.'
                    row[j+1] = '.'

    # Step 2: Mark cookies in each column
    for j in range(W):
        col = [row[j] for row in cookies]
        if len(set(col)) > 1:
            for i in range(H):
                if col[i] == col[i+1]:
                    col[i] = '.'
                    col[i+1] = '.'

    # Step 3: Remove marked cookies
    for i in range(H):
        for j in range(W):
            if cookies[i][j] == '.':
                cookies[i][j] = '.'

    # Count remaining cookies
    remaining_cookies = sum(1 for row in cookies for cookie in row if cookie != '.')

    return remaining_cookies

