def can_fit_in_lines(width, words, M):
    lines = 1
    current_width = 0

    for word in words:
        if current_width + word > width:
            lines += 1
            current_width = word
            if lines > M:
                return False
        else:
            current_width += word

    return True

def find_min_width(N, M, words):
    total_width = sum(words)
    low, high = 1, total_width

    while low < high:
        mid = (low + high) // 2
        if can_fit_in_lines(mid, words, M):
            high = mid
        else:
            low = mid + 1

    return low

