def atcoder_inc(N, K, P, plans):
    # Initialize the DP table with a large value (infinity)
    dp = [[[float('inf')] * (P + 1) for _ in range(P + 1)] for _ in range(N + 1)]
    dp[0][0][0] = 0

    # Iterate over each development plan
    for i in range(1, N + 1):
        C, *A = plans[i - 1]
        for j in range(P + 1):
            for k in range(P + 1):
                # Update the DP table by considering the new values of the parameters
                for j_new in range(P + 1):
                    for k_new in range(P + 1):
                        if j_new + A[0] <= P and k_new + A[1] <= P:
                            dp[i][j_new][k_new] = min(dp[i][j_new][k_new], dp[i - 1][j][k] + C)

    # Find the minimum cost to achieve the goal
    min_cost = float('inf')
    for j in range(P + 1):
        for k in range(P + 1):
            if j + A[0] >= P and k + A[1] >= P:
                min_cost = min(min_cost, dp[N][j][k])

    return min_cost if min_cost != float('inf') else -1

