def count_pairs(N, T, strings):
    # Precompute prefix and suffix matches
    prefix_matches = [0] * N
    suffix_matches = [0] * N

    for i in range(N):
        prefix_matches[i] = 0
        for j in range(len(T)):
            if T[j] == strings[i][j]:
                prefix_matches[i] += 1
            else:
                break

        suffix_matches[i] = 0
        for j in range(len(T) - 1, -1, -1):
            if T[j] == strings[i][-j - 1]:
                suffix_matches[i] += 1
            else:
                break

    # Count pairs
    count = 0
    for i in range(N):
        for j in range(N):
            if prefix_matches[i] + suffix_matches[j] >= len(T):
                count += 1

    return count

