def solve_abc_grid(N, R, C):
    # Check if the total count of A, B, and C is N
    if R.count('A') + R.count('B') + R.count('C') != N or C.count('A') + C.count('B') + C.count('C') != N:
        return "No"

    # Check the leftmost characters
    for i in range(N):
        if R[i] != grid[i][0]:
            return "No"

    # Check the topmost characters
    for j in range(N):
        if C[j] != grid[0][j]:
            return "No"

    # Fill the grid
    grid = [['.' for _ in range(N)] for _ in range(N)]

    def backtrack(row, col):
        if row == N:
            return True
        if col == N:
            return backtrack(row + 1, 0)

        if grid[row][col] != '.':
            return backtrack(row, col + 1)

        for char in ['A', 'B', 'C']:
            if char not in grid[row]:
                grid[row][col] = char
                if backtrack(row, col + 1):
                    return True
                grid[row][col] = '.'

        return False

    if backtrack(0, 0):
        return "Yes\n" + "\n".join("".join(row) for row in grid)
    else:
        return "No"

