from collections import deque

def is_bipartite(N, edges):
    color = [0] * (N + 1)  # 1-based indexing

    for u, v in edges:
        if color[u] == color[v]:
            return False
        if color[u] == 0:
            color[u] = 1
            color[v] = 0
            queue = deque([u])
            while queue:
                node = queue.popleft()
                for neighbor in range(1, N + 1):
                    if edges[node][neighbor] == 1:
                        if color[neighbor] == color[node]:
                            return False
                        if color[neighbor] == 0:
                            color[neighbor] = 1 - color[node]
                            queue.append(neighbor)
    return True

