def can_match(N, M, S, T):
    X = ['#'] * N

    for i in range(N):
        if X[i] == '#':
            continue

        # Check if we can match the current character in S with a substring of X
        for j in range(i - M + 1, i + 1):
            if X[j] == '#' or X[j] == T[0]:
                # Check if the substring X[j:j+M] matches T
                if X[j:j+M] == T:
                    # Replace the substring with T
                    for k in range(j, j+M):
                        X[k] = T[0]
                    break

    # Check if X matches S
    for i in range(N):
        if X[i] != S[i]:
            return "No"

    return "Yes"

