def find_nth_repunit_sum(n):
    repunits = [1]
    while len(repunits) < n:
        repunits.append(int('1' * len(repunits[-1])))

    repunits.sort()

    heap = [(1, 1, 1)]
    count = 0
    while heap and count < n:
        sum_repunits, r1, r2 = heapq.heappop(heap)
        count += 1
        if count == n:
            return sum_repunits

        for r3 in repunits[len(repunits) - 1:]:
            heapq.heappush(heap, (sum_repunits + r3, r1, r2))

