def count_connected_components(grid, H, W):
    visited = [[False] * W for _ in range(H)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] == '#':
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    count = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

def expected_value(grid, H, W):
    red_cells = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                red_cells.append((i, j))

    total_components = 0
    for i, j in red_cells:
        grid[i][j] = '#'
        new_components = count_connected_components(grid, H, W)
        total_components += new_components
        grid[i][j] = '.'

    expected_value = total_components / len(red_cells)

    # Find the modular inverse of len(red_cells) modulo MOD
    def mod_inverse(a, m):
        m0, x0, x1 = m, 0, 1
        if m == 1:
            return 0
        while a > 1:
            q = a // m
            m, a = a % m, m
            x0, x1 = x1 - q * x0, x0
        if x1 < 0:
            x1 += m0
        return x1

    inverse = mod_inverse(len(red_cells), MOD)
    expected_value = (expected_value * inverse) % MOD

    return expected_value

