import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def count_divisible(x, n, m, lcm_nm):
    return x // n + x // m - x // lcm_nm

def find_kth_number(N, M, K):
    lcm_nm = lcm(N, M)
    low, high = 1, 10**18  # Upper bound is chosen to be large enough
    while low < high:
        mid = (low + high) // 2
        count = count_divisible(mid, N, M, lcm_nm)
        if count < K:
            low = mid + 1
        else:
            high = mid

    # Now we have the smallest number X such that count_divisible(X, N, M, lcm_nm) >= K
    # We need to find the K-th number divisible by exactly one of N and M
    count = 0
    x = low
    while count < K:
        if x % N == 0 and x % M != 0:
            count += 1
        elif x % N != 0 and x % M == 0:
            count += 1
        x += 1

    return x - 1

