def is_perfect_square(n):
    root = int(math.sqrt(n))
    return root * root == n

def prime_factors(n):
    factors = {}
    d = 2
    while d * d <= n:
        while (n % d) == 0:
            if d in factors:
                factors[d] += 1
            else:
                factors[d] = 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = 1
    return factors

def count_square_pairs(N, A):
    factor_counts = Counter(A)
    square_pairs = 0

    for i in range(N):
        factors = prime_factors(A[i])
        for prime, exp in factors.items():
            if exp % 2 == 1:
                # We need to find a corresponding prime factor with an odd exponent
                # to make the sum of exponents even
                for prime2, exp2 in factor_counts.items():
                    if exp2 % 2 == 1:
                        square_pairs += factor_counts[prime2]
                        break

    return square_pairs

