class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert_after(self, x, y):
        current = self.head
        while current:
            if current.value == x:
                new_node = Node(y)
                new_node.prev = current
                new_node.next = current.next
                if current.next:
                    current.next.prev = new_node
                current.next = new_node
                if current == self.tail:
                    self.tail = new_node
                return
            current = current.next

    def remove(self, x):
        current = self.head
        while current:
            if current.value == x:
                if current.prev:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                if current.next:
                    current.next.prev = current.prev
                else:
                    self.tail = current.prev
                return
            current = current.next

    def to_list(self):
        result = []
        current = self.head
        while current:
            result.append(current.value)
            current = current.next
        return result

def process_queries(N, A, Q, queries):
    dll = DoublyLinkedList()
    for value in A:
        dll.insert_after(value, value)

    for query in queries:
        if query[0] == 1:
            x, y = query[1], query[2]
            dll.insert_after(x, y)
        elif query[0] == 2:
            x = query[1]
            dll.remove(x)

    return dll.to_list()

