def can_place_tiles(N, H, W, tiles):
    total_area = H * W
    total_tile_area = sum(A * B for A, B in tiles)

    if total_tile_area < total_area:
        return "No"

    # Try to place the tiles in different configurations
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if (i + 1) * (j + 1) + (k + 1) * (l + 1) == total_area:
                        # Check if the tile can fit in the grid
                        if (i + 1) * (j + 1) <= H and (k + 1) * (l + 1) <= W:
                            # Check if the tile can be placed in the grid
                            if (i + 1) * (j + 1) + (k + 1) * (l + 1) == total_area:
                                # Check if the tile can be placed without extending outside the grid
                                if (i + 1) * (j + 1) + (k + 1) * (l + 1) <= H * W:
                                    return "Yes"

    return "No"

