def paint_grid(H, W, M, operations):
    # Initialize the grid with all cells painted with color 0
    grid = [[0] * W for _ in range(H)]

    # Process each operation
    for T, A, X in operations:
        if T == 1:
            # Repaint all cells in the A-th row with color X
            for j in range(W):
                grid[A-1][j] = X
        elif T == 2:
            # Repaint all cells in the A-th column with color X
            for i in range(H):
                grid[i][A-1] = X

    # Count the number of cells painted with each color
    color_count = {}
    for row in grid:
        for cell in row:
            if cell in color_count:
                color_count[cell] += 1
            else:
                color_count[cell] = 1

    # Prepare the output
    K = len(color_count)
    output = []
    for color in sorted(color_count.keys()):
        output.append(f"{color} {color_count[color]}")

    return K, "\n".join(output)

