def is_airport_code(S, T):
    # Check if T is a subsequence of S
    i, j = 0, 0
    while i < len(S) and j < len(T):
        if S[i] == T[j]:
            j += 1
        i += 1

    # If we have matched all characters of T, it is a subsequence
    if j == len(T):
        # Check if the last character of T is 'X'
        if T[-1] == 'X':
            return "Yes"
        else:
            return "No"
    else:
        return "No"

