def is_good_string(S):
    from collections import Counter

    # Count the frequency of each character in the string
    freq = Counter(S)

    # Group characters by their frequency
    freq_count = {}
    for char, count in freq.items():
        if count in freq_count:
            freq_count[count].append(char)
        else:
            freq_count[count] = [char]

    # Check the condition for each frequency
    for count in freq_count:
        if len(freq_count[count]) not in (0, 2):
            return "No"

    return "Yes"

