def game(grid):
    memo = {}

    def is_terminal(grid):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    return False
        return True

    def score(grid, player):
        score = 0
        for i in range(3):
            for j in range(3):
                if grid[i][j] == player:
                    score += grid[i][j]
        return score

    def is_valid(grid, i, j, player):
        if i < 0 or i >= 3 or j < 0 or j >= 3:
            return False
        if grid[i][j] != 0:
            return False
        if player == 1:
            return (i == 0 or i == 1 or i == 2) and (j == 0 or j == 1 or j == 2)
        if player == 2:
            return (i == 0 or i == 1 or i == 2) and (j == 0 or j == 1 or j == 2)
        return True

    def dfs(grid, player, memo):
        if (tuple(tuple(row) for row in grid), player) in memo:
            return memo[(tuple(tuple(row) for row in grid), player)]
        if is_terminal(grid):
            memo[(tuple(tuple(row) for row in grid), player)] = (score(grid, player), player)
            return memo[(tuple(tuple(row) for row in grid), player)]

        best_score = float('-inf') if player == 1 else float('inf')
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    new_grid = [row[:] for row in grid]
                    new_grid[i][j] = player
                    if player == 1:
                        if is_valid(new_grid, i, j, 1):
                            result = dfs(new_grid, 2, memo)
                            if result[0] > best_score:
                                best_score = result[0]
                                memo[(tuple(tuple(row) for row in new_grid), player)] = (best_score, player)
                    else:
                        if is_valid(new_grid, i, j, 2):
                            result = dfs(new_grid, 1, memo)
                            if result[0] < best_score:
                                best_score = result[0]
                                memo[(tuple(tuple(row) for row in new_grid), player)] = (best_score, player)
        memo[(tuple(tuple(row) for row in grid), player)] = (best_score, player)
        return memo[(tuple(tuple(row) for row in grid), player)]

    result = dfs(grid, 1, memo)
    if result[0] > result[1]:
        return "Takahashi"
    else:
        return "Aoki"

