def solve(N, A):
    operations = []
    for i in range(N):
        if A[i] != i + 1:
            for j in range(i + 1, N):
                if A[j] != j + 1:
                    operations.append((i + 1, j + 1))
                    A[i], A[j] = A[j], A[i]
                    break
    return len(operations), operations

