def longest_common_prefix(s1, s2):
    min_len = min(len(s1), len(s2))
    lcp = 0
    for i in range(min_len):
        if s1[i] != s2[i]:
            break
        lcp += 1
    return lcp

def sum_of_lcp(strings):
    n = len(strings)
    prefix_sum = [0] * n

    for i in range(n):
        for j in range(i + 1, n):
            lcp = longest_common_prefix(strings[i], strings[j])
            prefix_sum[i] += lcp
            prefix_sum[j] += lcp

    total_sum = 0
    for i in range(n):
        for j in range(i + 1, n):
            total_sum += prefix_sum[i] - prefix_sum[j]

    return total_sum

