def min_boxes(apple, capacity):
    total_apples = sum(apple)
    total_capacity = sum(capacity)

    if total_apples <= total_capacity:
        return 1

    boxes_used = 1
    remaining_capacity = total_capacity - capacity[0]

    for i in range(1, len(capacity)):
        if remaining_capacity >= apple[i]:
            remaining_capacity -= apple[i]
        else:
            boxes_used += 1
            remaining_capacity = total_capacity - capacity[i]

    return boxes_used

