def shortest_unique_substring(arr):
    n = len(arr)
    answer = [""] * n

    for i in range(n):
        for j in range(i + 1, len(arr[i]) + 1):
            substring = arr[i][i:j]
            if all(substring not in arr[k] for k in range(n) if k != i):
                if not answer[i] or len(substring) < len(answer[i]) or (len(substring) == len(answer[i]) and substring < answer[i]):
                    answer[i] = substring

    return answer

