def min_deletions_to_k_special(word, k):
    freq = Counter(word)
    max_freq = max(freq.values())
    min_deletions = 0

    for freq_val in freq.values():
        if freq_val > max_freq + k:
            min_deletions += freq_val - (max_freq + k)

    return min_deletions

def minMoves(nums, k, maxChanges):
    n = len(nums)
    ones = [i for i, x in enumerate(nums) if x == 1]

    if len(ones) >= k:
        return 0

    if maxChanges >= k:
        return k

    moves = 0
    i = 0
    j = 0

    while i < len(ones) and j < len(nums):
        if ones[i] == ones[j]:
            i += 1
            j += 1
        elif ones[i] < ones[j]:
            if maxChanges > 0:
                maxChanges -= 1
                j += 1
            else:
                moves += 1
                j += 1
        else:
            if maxChanges > 0:
                maxChanges -= 1
                i += 1
            else:
                moves += 1
                i += 1

    return moves

def max_length(s):
    max_len = 0
    left = 0
    char_count = {}

    for right in range(len(s)):
        char_count[s[right]] = char_count.get(s[right], 0) + 1

        while len(char_count) > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def most_frequent_ids(nums, freq):
    from collections import defaultdict

    counts = defaultdict(int)
    ans = []

    for i in range(len(nums)):
        num = nums[i]
        freq_val = freq[i]

        if freq_val > 0:
            counts[num] += freq_val
        else:
            counts[num] -= freq_val

        ans.append(max(counts.values()))

    return ans

def longest_common_suffix(wordsContainer, wordsQuery):
    def suffix_length(word):
        return len(word) - len(word.rstrip('a'))

    def longest_common_suffix_length(word1, word2):
        i = 0
        while i < len(word1) and i < len(word2) and word1[i] == word2[i]:
            i += 1
        return i

    def find_longest_common_suffix(word, wordsContainer):
        max_length = 0
        min_length = float('inf')
        min_index = -1
        for i, w in enumerate(wordsContainer):
            length = suffix_length(w)
            if length > max_length:
                max_length = length
                min_length = length
                min_index = i
            elif length == max_length:
                if length < min_length:
                    min_length = length
                    min_index = i
                elif length == min_length:
                    if i < min_index:
                        min_index = i
        return min_index

    ans = []
    for query in wordsQuery:
        ans.append(find_longest_common_suffix(query, wordsContainer))
    return ans

