def lexicographically_smallest_string(s, k):
    s = list(s)
    n = len(s)
    for i in range(n):
        if k == 0:
            break
        if s[i] != 'a':
            k -= 1
            s[i] = 'a'
    for i in range(n - 1, -1, -1):
        if k == 0:
            break
        if s[i] != 'z':
            k -= 1
            s[i] = 'z'
    return ''.join(s)

