def min_levels_to_gain_more_points(possible):
    total_points = sum(1 if x == 1 else -1 for x in possible)
    if total_points == 0:
        return -1

    alice_points = 0
    for i in range(len(possible)):
        if possible[i] == 1:
            alice_points += 1
        else:
            break

    bob_points = total_points - alice_points

    if alice_points > bob_points:
        return 1

    for i in range(len(possible)):
        if possible[i] == 1:
            alice_points += 1
        else:
            break

    bob_points = total_points - alice_points

    if alice_points > bob_points:
        return i + 1

    return -1

def sum_of_powers(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
            if j > 1:
                dp[i][j] -= dp[i - 1][j - 2]
            dp[i][j] %= MOD

    return dp[n][k]

