        for j in range(i, n):
            if nums[j] not in seen:
                seen.add(nums[j])
                distinct_count += 1
            uniqueness_array.append(distinct_count)

    uniqueness_array.sort()
    m = len(uniqueness_array)

    if m % 2 == 1:
        return uniqueness_array[m // 2]
    else:
        return uniqueness_array[m // 2 - 1]

def is_valid_word(word):
    vowels = set('aeiouAEIOU')
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')
    if len(word) < 3:
        return False
    if not word.isalnum():
        return False
    if not any(c in vowels for c in word):
        return False
    if not any(c in consonants for c in word):
        return False
    return True

def min_operations(word, k):
    n = len(word)
    count = [0] * k
    for i in range(n):
        count[i % k] += 1
    operations = 0
    for i in range(k):
        if count[i] > 0:
            operations += count[i] // 2
            count[i] %= 2
    return operations

from collections import Counter

def min_length_of_anagram(s):
    count = Counter(s)
    min_length = float('inf')
    for length in range(1, len(s) + 1):
        if all(count[c] % length == 0 for c in count):
            min_length = min(min_length, length)
    return min_length

def can_form_square(grid):
    # Check all possible 2x2 squares in the grid
    for i in range(2):
        for j in range(2):
            # Count the number of 'B' and 'W' in the current 2x2 square
            count_B = 0
            count_W = 0
            for x in range(i, i+2):
                for y in range(j, j+2):
                    if grid[x][y] == 'B':
                        count_B += 1
                    else:
                        count_W += 1
            # If there are at most one 'B' or 'W', we can form a 2x2 square of the same color
            if count_B <= 1 or count_W <= 1:
                return True
    return False

def count_right_triangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                for k in range(len(grid)):
                    for l in range(len(grid[0])):
                        if grid[k][l] == 1:
                            if (i == k and j == l) or (i == l and j == k):
                                count += 1
    return count

def count_stable_binary_arrays(zero, one, limit):
    MOD = 10**9 + 7

    def count_ways(arr, zero, one, limit):
        if len(arr) == limit:
            return 1 if arr.count(0) == zero and arr.count(1) == one else 0

        ways = 0
        for i in range(len(arr)):
            if arr[i] == 0:
                ways += count_ways(arr + [1], zero, one, limit)
            elif arr[i] == 1:
                ways += count_ways(arr + [0], zero, one, limit)

        return ways % MOD

    return count_ways([0], zero, one, limit)

def max_energy(energy, k):
    max_energy = float('-inf')
    for i in range(len(energy)):
        current_energy = 0
        j = i
        while j < len(energy):
            current_energy += energy[j]
            j += k
        max_energy = max(max_energy, current_energy)
    return max_energy

def is_special_array(nums):
    for i in range(len(nums) - 1):
        if (nums[i] % 2 == nums[i + 1] % 2):
            return False
    return True

def count_ways(k):
    if k == 0:
        return 2

    ways = [0] * (k + 1)
    ways[0] = 1
    ways[1] = 2

    for i in range(2, k + 1):
        ways[i] = ways[i - 1] + ways[i - 2]

    return ways[k]

def count_good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % (nums2[j] * k) == 0:
                count += 1
    return count

def max_sum_non_adjacent(nums):
    if not nums:
        return 0
    dp = [0] * len(nums)
    dp[0] = max(0, nums[0])
    if len(nums) > 1:
        dp[1] = max(dp[0], nums[1])
    for i in range(2, len(nums)):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])
    return dp[-1]

def max_sum_non_adjacent_queries(nums, queries):
    MOD = 10**9 + 7
    total_sum = 0
    for pos, x in queries:
        nums[pos] = x
        total_sum = (total_sum + max_sum_non_adjacent(nums)) % MOD
    return total_sum

def min_partitions(s):
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1

    total_count = sum(count)
    partitions = 0

    for i in range(26):
        if count[i] == 0:
            continue
        if count[i] == total_count // 2:
            partitions += 1
            count[i] = 0

    return partitions

def powerful_array(x):
    result = []
    while x > 0:
        result.append(x & -x)
        x >>= 1
    return sorted(result)

def calculate_product(from_i, to_i, mod_i):
    product = 1
    for i in range(from_i, to_i + 1):
        product = (product * powerful_array(i)) % mod_i
    return product

def solve(queries):
    answer = []
    for from_i, to_i, mod_i in queries:
        answer.append(calculate_product(from_i, to_i, mod_i))
    return answer

def xor_of_duplicates(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    result = 0
    for num, freq in count.items():
        if freq == 2:
            result ^= num

    return result

def find_occurrences(nums, queries, x):
    occurrences = []
    for num in nums:
        if num == x:
            occurrences.append(nums.index(num))
    return [occurrences[i] if i < len(occurrences) else -1 for i in queries]
